#!/usr/bin/env node
// End-to-end tests for the time-axis diagnostics over real CSV files:
// parse → diagnose → derived signals → summary text, plus a cross-check that the
// lazy (DuckDB) SQL agrees with the eager pass on the same bytes.
//
// The fixtures in test-files/csv/time-axis/ are generated by
// scripts/gen-time-axis-fixtures.mjs and committed; every expected number below
// is derived by hand from the file's contents, not copied from a program run.
//
// Companion suite: test-time-axis-variables.mjs covers the same logic at the
// unit level with in-memory arrays. This one starts from bytes on disk, so it
// also catches what the CSV parser does before the diagnostics ever run.
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import duckdbPkg from 'duckdb';
import CsvParser from '../src/parsers/csv-parser.js';
import { installDerivedMethods } from '../src/app/methods/derived-methods.js';
import { installTimeAxisInspectorMethods } from '../src/app/methods/time-axis-inspector-methods.js';
import { installPlotDataMethods } from '../src/plots/methods/data-methods.js';
import {
    computeTimeAxisDiagnostics,
    finalizeTimeAxisDiagnostics,
    mergeTimeAxisSteps,
    rawFromTimeAxisSummary,
    buildTimeAxisSummarySql,
    buildTimeAxisStepsSql,
    TIME_AXIS_GAP_FACTOR,
} from '../src/data/time-axis-diagnostics.js';
import { runDuckDb, closeDuckDbConnection, closeDuckDbDatabase, sqlPath } from '../src/data/csv-to-parquet-core.js';

const { Database } = duckdbPkg;
const FIXTURES = join('test-files', 'csv', 'time-axis');
const parser = new CsvParser();

class PlotManagerStub {
    constructor() { this.files = new Map(); }
}
installPlotDataMethods(PlotManagerStub);

class Harness {
    constructor() {
        this.activeFileId = 'f1';
        this.files = new Map([['f1', { name: 'fixture.csv' }]]);
        this.derivedByFile = new Map();
        this.dataToolVariablesByFile = new Map();
        this.plotManager = new PlotManagerStub();
        this.parser = parser;
        this._renderFilteredTree = () => {};
        this._rebuildPlotsUsingVariable = () => {};
    }
}
installDerivedMethods(Harness);
installTimeAxisInspectorMethods(Harness);

async function loadFixture(name) {
    const buffer = readFileSync(join(FIXTURES, name));
    const data = await parser.parse(buffer.buffer.slice(buffer.byteOffset, buffer.byteOffset + buffer.byteLength));
    const h = new Harness();
    h.plotManager.files.set('f1', { data });
    const timeVar = h._getActiveTimeVar(data);
    assert.ok(timeVar?.data?.length, `${name}: no time vector parsed`);
    return { name, data, h, timeVar, diagnostics: computeTimeAxisDiagnostics(timeVar.data, h._timeAxisSecondsScale(timeVar)) };
}

// Δt values carry float noise from decimal round-tripping; compare with a
// tolerance rather than pretending 0.1 + 0.1 is exact.
const near = (actual, expected, message, epsilon = 1e-9) =>
    assert.ok(Math.abs(actual - expected) <= epsilon, `${message} (got ${actual}, want ${expected})`);

const results = new Map();

// ── uniform.csv — the negative control ────────────────────────────────────────
{
    const f = await loadFixture('uniform.csv');
    results.set(f.name, f);
    const d = f.diagnostics;
    assert.equal(d.nSamples, 30, 'every row parsed');
    assert.equal(f.data.metadata.skippedInvalidTimeRows, 0);
    assert.equal(d.intervals, 29);
    assert.equal(d.steps, 29);
    assert.equal(d.span, 29);
    assert.deepEqual([d.dtMin, d.dtMean, d.dtMax], [1, 1, 1]);
    assert.deepEqual([d.repeated, d.gaps, d.backwards], [0, 0, 0]);
    assert.equal(d.verdict, 'equidistant', 'a clean file must not raise anything');
    assert.equal(f.h._timeAxisSummaryLine(d), '30 samples · Δt 1 s · equidistant');
}

// ── gaps.csv — 0…9, 15…24, 30…34: two stretches missing ───────────────────────
{
    const f = await loadFixture('gaps.csv');
    results.set(f.name, f);
    const d = f.diagnostics;
    assert.equal(d.nSamples, 25);
    assert.equal(d.intervals, 24);
    assert.equal(d.span, 34);
    assert.equal(d.dtMin, 1);
    assert.equal(d.dtMax, 6, 'the widest hole is 10→15');
    near(d.dtMean, 34 / 24, 'mean over the advancing intervals');
    // Threshold = 1.5 × (34/24) ≈ 2.125, so only the two 6 s jumps qualify.
    assert.equal(d.gaps, 2);
    assert.deepEqual([d.repeated, d.backwards], [0, 0]);
    assert.equal(d.verdict, 'irregular');
    assert.equal(f.h._timeAxisSummaryLine(d), '25 samples · Δt 1 s–6 s · 2 gaps');

    // Δt must spike exactly at the two holes and nowhere else.
    const delta = f.h._createOrUpdateTimeAxisVariable('f1', 'delta');
    const spikes = [...delta.data].map((v, i) => [i, v]).filter(([, v]) => v > 1.5);
    assert.deepEqual(spikes.map(([i]) => i), [10, 20], 'the spikes land on the samples after each hole');
    assert.deepEqual(spikes.map(([, v]) => v), [6, 6]);
}

// ── repeated.csv — uniform 0.1 s with two duplicated instants ─────────────────
{
    const f = await loadFixture('repeated.csv');
    results.set(f.name, f);
    const d = f.diagnostics;
    assert.equal(d.nSamples, 23, '21 grid samples + 2 duplicates');
    assert.equal(d.intervals, 22);
    assert.equal(d.steps, 20, 'the duplicates do not advance time');
    assert.equal(d.repeated, 2);
    near(d.dtMin, 0.1, 'the minimum is the real step, not the zero-length interval');
    near(d.dtMean, 0.1, 'span divided by the advancing intervals');
    near(d.dtMax, 0.1);
    assert.equal(d.gaps, 0);
    assert.equal(d.verdict, 'equidistantRepeats', 'a Modelica event must not read as irregular');
    assert.equal(f.h._timeAxisSummaryLine(d), '23 samples · Δt 100 ms · 2 repeated times');

    // The index climbs vertically where the timestamps repeat: two samples share
    // an x, and their index values differ by exactly one.
    const index = f.h._createOrUpdateTimeAxisVariable('f1', 'index');
    const time = f.timeVar.data;
    const ties = [...time].map((t, i) => i).filter(i => i > 0 && time[i] === time[i - 1]);
    assert.equal(ties.length, 2);
    for (const i of ties) assert.equal(index.data[i] - index.data[i - 1], 1);
    assert.equal(f.h.plotManager._variableDefaultsToStairs(index), true, 'so it is drawn as stairs');

    const delta = f.h._createOrUpdateTimeAxisVariable('f1', 'delta');
    for (const i of ties) assert.equal(delta.data[i], 0, 'Δt is zero across a repeated instant');
}

// ── backwards.csv — the file says 0…4, 3.5, 6…9; the parser sorts it ──────────
{
    const f = await loadFixture('backwards.csv');
    results.set(f.name, f);
    // _sortTimeSeriesByTime reorders non-monotonic rows, so a CSV can never hand
    // the diagnostic a reversal. Pin that, because it is why the "time going
    // backwards" row reads 0 for every CSV a user will ever open.
    assert.deepEqual(Array.from(f.timeVar.data), [0, 1, 2, 3, 3.5, 4, 6, 7, 8, 9],
        'the out-of-order sample is sorted into place');

    const d = f.diagnostics;
    assert.equal(d.nSamples, 10);
    assert.equal(d.intervals, 9);
    assert.equal(d.backwards, 0, 'nothing steps backwards once the rows are ordered');
    assert.equal(d.dtMin, 0.5, 'the reversal became two half-steps');
    assert.equal(d.dtMax, 2, 'and a double step where 4 → 6');
    assert.equal(d.span, 9);
    near(d.dtMean, 1);
    assert.equal(d.gaps, 1, 'the 2 s jump clears the 1.5 s threshold');
    assert.equal(d.repeated, 0);
    assert.equal(d.verdict, 'irregular');
    assert.equal(f.h._timeAxisSummaryLine(d), '10 samples · Δt 0.5 s–2 s · 1 gap');
}

// The reversal counter itself, where a format that preserves file order can
// reach it — the CSV path structurally cannot.
{
    const d = computeTimeAxisDiagnostics([0, 1, 2, 3, 4, 3.5, 6, 7, 8, 9]);
    assert.equal(d.backwards, 1, 'the 4 → 3.5 step is counted in file order');
    assert.equal(d.dtMin, -0.5, 'and the negative interval is reported as such');
    assert.equal(d.dtMax, 2.5);
    assert.equal(d.verdict, 'irregular');
}

// ── nan-time.csv — an unparseable cell costs the whole time axis ──────────────
{
    const f = await loadFixture('nan-time.csv');
    results.set(f.name, f);
    // 30 rows, three of them carrying '', 'NaN' and 'bad' in the time column.
    // The parser does not drop those rows: it refuses the column as the axis and
    // generates a row index, demoting the timestamps to an ordinary variable.
    // Worth pinning, because the consequence is easy to miss — the inspector
    // then describes row numbers, and calls them perfectly equidistant.
    assert.equal(f.data.metadata.timeName, 'index', 'the time column was rejected as the axis');
    assert.equal(f.data.metadata.timeKind, 'index');
    assert.equal(f.data.variables.time?.kind, 'variable', 'and survives as a plain variable');

    const d = f.diagnostics;
    assert.equal(d.nSamples, 30, 'no row is lost — the axis changed, not the data');
    assert.equal(d.unitless, true, 'a row index has no time unit');
    assert.equal(d.dtMean, 1);
    assert.equal(d.verdict, 'equidistant');
    // Unitless means the numbers are printed as plain step counts, no seconds.
    assert.equal(f.h._timeAxisSummaryLine(d), '30 samples · Δt 1 · equidistant');
    assert.equal(f.h._formatTimeAxisSpan(d.span, d.unitless), '29', 'no unit is invented for step counts');
}

// The CSV path can never deliver a NaN timestamp, but MAT and Parquet can, so
// the array-level guard is tested where it actually applies.
{
    const d = computeTimeAxisDiagnostics([0, 1, NaN, 3, Infinity, 5]);
    assert.equal(d.nSamples, 4, 'non-finite samples are skipped, not counted');
    assert.equal(d.intervals, 3);
    assert.equal(d.dtMax, 2, 'and the neighbours close over them');
}

// ── jitter.csv — irregular sampling with nothing missing ──────────────────────
{
    const f = await loadFixture('jitter.csv');
    results.set(f.name, f);
    const d = f.diagnostics;
    assert.equal(d.nSamples, 200);
    assert.equal(d.intervals, 199);
    assert.ok(d.dtMin >= 0.899 && d.dtMin < 1, `dtMin within the ±10% band (got ${d.dtMin})`);
    assert.ok(d.dtMax <= 1.101 && d.dtMax > 1, `dtMax within the ±10% band (got ${d.dtMax})`);
    assert.ok(Math.abs(d.dtMean - 1) < 0.02, `the mean stays near the nominal step (got ${d.dtMean})`);
    // This is the point of the case: jittery is not the same as broken.
    assert.deepEqual([d.repeated, d.gaps, d.backwards], [0, 0, 0],
        '±10% jitter must not be reported as gaps, duplicates or reversals');
    assert.equal(d.verdict, 'irregular', 'but 10% is decisively not equidistant');
    // The gap threshold is 1.5× the mean; the jitter band tops out well below it.
    assert.ok(d.dtMax < TIME_AXIS_GAP_FACTOR * d.dtMean, 'the jitter band cannot reach the gap threshold');
}

// ── mixed.csv — 3 repeated, 2 gaps, 1 sample sorted back into place ───────────
{
    const f = await loadFixture('mixed.csv');
    results.set(f.name, f);
    const d = f.diagnostics;
    assert.equal(f.data.metadata.timeKind, 'numeric', 'the timestamps are still the axis here');
    assert.equal(d.nSamples, 17);
    assert.equal(d.intervals, 16);
    assert.equal(d.steps, 13, 'three intervals do not advance time');
    // Deliberately distinct counts: a swapped counter cannot hide behind them.
    assert.equal(d.repeated, 3);
    assert.equal(d.gaps, 2);
    assert.equal(d.backwards, 0, 'the 14 → 13.5 row was sorted, as in backwards.csv');
    assert.equal(d.dtMin, 0.5);
    assert.equal(d.dtMax, 7);
    assert.equal(d.span, 23);
    near(d.dtMean, 23 / 13);
    assert.equal(d.verdict, 'irregular');
    assert.equal(f.h._timeAxisSummaryLine(d),
        '17 samples · Δt 0.5 s–7 s · 3 repeated times, 2 gaps');
}

// ── The lazy SQL must agree with the eager pass on the same bytes ─────────────
// This is the only place the two-phase DuckDB queries actually execute; without
// it they are covered by text matching alone.
{
    const db = new Database(':memory:');
    const conn = db.connect();
    try {
        for (const [name, f] of results) {
            const eager = f.diagnostics;
            const path = sqlPath(join(FIXTURES, name));
            const view = `v_${name.replace(/[^a-z0-9]/gi, '_')}`;
            // Mirror the axis the eager parser actually chose, or the two sides
            // would be describing different things. Where it fell back to a row
            // index, so does this — the same expression _timeExpressionSql emits
            // for a generated-time file. Elsewhere TRY_CAST stands in for the
            // parser's numeric read, leaving unparseable cells NULL for the SQL
            // to filter out.
            const timeExpr = f.data.metadata.timeKind === 'index'
                ? '(ROW_NUMBER() OVER () - 1)::DOUBLE'
                : 'TRY_CAST(time AS DOUBLE)';
            await runDuckDb(conn, `CREATE OR REPLACE VIEW ${view} AS
                SELECT ${timeExpr} AS t FROM read_csv_auto('${path}', header = true)`);

            const [summary] = await runDuckDb(conn, buildTimeAxisSummarySql('t', view));
            const raw = rawFromTimeAxisSummary({
                n: Number(summary.n),
                tMin: Number(summary.t_min),
                tMax: Number(summary.t_max),
                nDistinct: Number(summary.n_distinct),
            });
            const phase1 = finalizeTimeAxisDiagnostics(raw);
            assert.equal(phase1.nSamples, eager.nSamples, `${name}: sample count`);
            assert.equal(phase1.repeated, eager.repeated, `${name}: repeated timestamps`);
            near(phase1.span, eager.span, `${name}: span`);
            near(phase1.dtMean, eager.dtMean, `${name}: mean Δt`);
            assert.equal(phase1.verdict, null, `${name}: phase 1 alone reaches no verdict`);

            const threshold = phase1.dtMean * TIME_AXIS_GAP_FACTOR;
            const [steps] = await runDuckDb(conn, buildTimeAxisStepsSql('t', view, threshold, v => String(v)));
            const phase2 = finalizeTimeAxisDiagnostics(mergeTimeAxisSteps(raw, {
                dtMin: Number(steps.dt_min),
                dtMax: Number(steps.dt_max),
                gaps: Number(steps.n_gaps),
            }));

            near(phase2.dtMin, eager.dtMin, `${name}: min Δt`);
            near(phase2.dtMax, eager.dtMax, `${name}: max Δt`);
            assert.equal(phase2.gaps, eager.gaps, `${name}: gap count`);
            assert.equal(phase2.verdict, eager.verdict, `${name}: verdict`);
            // The one honest divergence: the sorted SQL walk cannot inspect file
            // order, so it reports "not checked" rather than a confident zero.
            assert.equal(phase2.backwards, null, `${name}: the lazy path cannot check file order`);
            assert.equal(eager.backwards, 0, `${name}: and the CSV parser sorted any reversal away`);
        }
    } finally {
        await closeDuckDbConnection(conn);
        await closeDuckDbDatabase(db);
    }
}

console.log(`Time-axis fixture tests passed (${results.size} CSV files, eager + DuckDB).`);
